    assert(!is_prime(6));
    assert(!is_prime(8));
    assert(!is_prime(9));
    
    // Edge case: largest i8 value (127 is prime)
    assert(is_prime(127));
    
    // Composite numbers
    assert(!is_prime(100));
    assert(!is_prime(121));  // 11*11
